public static void main(String[] args) {
    PrintWriter out = new PrintWriter(System.out);
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();
    int[] X = new int[M];
    for (int i = 0; i < M; i++) {
        X[i] = sc.nextInt();
    }

    long totalDistance = 0;
    for (int i = 0; i < M - 1; i++) {
        totalDistance += Math.min(Math.abs(X[i + 1] - X[i]), N - Math.abs(X[i + 1] - X[i]));
    }

    long maxSavings = 0;
    for (int i = 0; i < M - 1; i++) {
        long currentSavings = Math.abs(X[i + 1] - X[i]) - Math.min(Math.abs(X[i + 1] - X[i]), N - Math.abs(X[i + 1] - X[i]));
        maxSavings = Math.max(maxSavings, currentSavings);
    }

    out.println(totalDistance - maxSavings);
    out.flush();
}
